#include <bits/stdc++.h>
using namespace std;
#define ll long long

int main() {
	// your code goes here
    int t;cin>>t;
    while(t--){
        ll n;cin>>n;
        int x = 3*n;
        vector<ll> num(x);
        for(ll i=0;i<x;i++) cin>>num[i];
        
        sort(num.rbegin(), num.rend());
        vector<ll> dp(x+1, 0);
        for(ll i = 0; i<x; i++) dp[i+1] = dp[i] + num[i];
        
        ll maxi = -1;
        for(ll i=0;i<=n;i++){
            ll low = 1, high = n-i;
            ll besty = 0;
            while(low<= high){
                ll mid = low + (high-low)/2;
                ll a1 = num[i + 2 * mid-2];
                ll a2 = num[i+2 * mid - 1];
                ll a3 = num[3*n - 2*i - mid];
                ll val = a1 + a2 - 3*a3;
                if(val >= 0){
                    besty = mid;
                    low = mid+1;
                }
                else{
                    high = mid-1;
                }
            }
                for(ll j=max(0ll, besty - 1); j<= min(n-i, besty+1); j++){
                    ll cur = 2*dp[i] + dp[i+2*j] + 3*dp[3*n - 2*i - j];
                    maxi = max(maxi, cur);
                }
            
        }
        cout<<maxi<<"\n";
    }
    return 0;
}
